<script setup lang="ts">
import{computed,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import AppHeader from'../../components/AppHeader.vue';import StatusNotice from'../../components/StatusNotice.vue';import{api}from'../../api/client';import type{OrderProjection}from'../../domain/types'
const p=ref<OrderProjection|null>(null),orderRef=ref(''),loading=ref(false),error=ref('');const rConfirmed=computed(()=>p.value?.facts.refund==='CONFIRMED');const lClosed=computed(()=>p.value?.facts.accounting==='CONFIRMED');const lateConflict=computed(()=>rConfirmed.value&&p.value?.facts.delivery==='CONFIRMED')
async function refresh(){if(!orderRef.value){error.value='缺少订单引用；R/L/D 均保持 UNKNOWN。';return}loading.value=true;error.value='';try{p.value=await api.getProjection(orderRef.value)}catch{p.value=null;error.value='权威投影读取失败；R/L/D 均保持 UNKNOWN。'}finally{loading.value=false}}
onLoad(q=>{orderRef.value=typeof q?.orderRef==='string'?decodeURIComponent(q.orderRef):'';refresh()});const fact=(s?:string)=>s||'UNKNOWN'
</script>
<template><view class="page"><AppHeader left="← 订单" right="申诉" @left="uni.navigateBack()"/><view class="content"><text class="kicker">退款与冲突 / UX-P015</text><view class="heading" role="heading" aria-level="1">退款记录核对</view><text class="desc">退款事实、本地记录与到账事实分别保留，不用一个状态互相替代。</text><StatusNotice v-if="error" tone="risk" title="读取错误">{{error}}</StatusNotice><view class="card facts"><view><text>外部退款事实 R</text><text :class="rConfirmed?'ok':'unknown'">{{fact(p?.facts.refund)}}</text></view><view><text>本地退款账务 L</text><text :class="lClosed?'ok':'unknown'">{{fact(p?.facts.accounting)}}</text></view><view><text>用户到账事实 D</text><text :class="p?.facts.delivery==='CONFIRMED'?'ok':'unknown'">{{fact(p?.facts.delivery)}}</text></view></view><StatusNotice v-if="rConfirmed&&!lClosed" tone="unknown" title="外部退款已确认，本地记录核对中">只补缺失账务；不会再次退款，也不会提前显示完整“已退款”。</StatusNotice><StatusNotice v-if="lateConflict" tone="risk" title="退款后发现迟到到账">R 与 D 两项事实均保留，订单进入 REVIEW；不得静默关闭或重复退款。</StatusNotice></view><view class="action"><button class="primary" :disabled="loading||!orderRef" @click="refresh">只读查询退款进度</button><button class="secondary" @click="uni.navigateTo({url:'/pages/support/case'})">客服与申诉</button></view></view></template>
<style src="../../styles/shared.css"></style><style scoped>.facts view{display:flex;justify-content:space-between;padding:14rpx 0}.ok{color:var(--success);font-weight:800}.unknown{color:var(--unknown);font-weight:800}</style>
